bool solve(Node* node, vector<int> &wins, int &totalWins) {
    if (node->type == 't') {
        totalWins = 0;
        return true;
    }
    // match node
    int leftWins = 0, rightWins = 0;
    if (!solve(node->l, wins, leftWins)) return false;
    if (!solve(node->r, wins, rightWins)) return false;

    // The winner of this match must have totalWins = max(leftWins, rightWins) + 1
