    // We know the winner's index from the reported wins structure?
    // Actually we don't know who wins from the string (no winner info).
    // So we must consider both possibilities.

    // Option 1: left wins
    if (wins[node->l->idx] == leftWins + 1 && wins[node->r->idx] == rightWins) {
        totalWins = leftWins + 1;
        node->idx = node->l->idx;
        return true;
    }
    // Option 2: right wins
