/*
We parse the tournament chart recursively.

Grammar:
- A leaf is a contestant name: a non-empty string of lowercase letters.
- An internal node is: '[' left '-' winner '-' right ']'
  where winner is the name of the contestant who won the match between
  the winners of left and right subtrees.

For each subtree, we compute all possible mappings:
  contestant -> number of wins inside this subtree
that are consistent with the chart.

Leaf:
  only one possible state: {name : 0}, champion = name

Internal node:
  combine every possible state from left and right.
  Let cl, cr be champions of the chosen left/right states.
  The declared winner w must be either cl or cr.
  Then merge the win counts and add +1 to w.

Finally compare against the reported counts.

Input format assumed from the original JAG problem:
- First line: chart string S
- Then zero or more lines, each: name wins
  until EOF

If a contestant appears in the report but not in the chart, impossible.
If a contestant appears in the chart but not in the report, its reported wins are assumed 0?
Usually all contestants are listed, but to be safe we require exact equality over all
contestants mentioned in the chart, treating missing report as 0.
*/

struct Node {
    bool leaf;
    string name;   // for leaf: contestant name, for internal: declared winner
    Node *l = nullptr, *r = nullptr;
};

string S;
int posi = 0;

string parseName() {
    string t;
    while (posi < (int)S.size() && 'a' <= S[posi] && S[posi] <= 'z') {
        t += S[posi++];
    }
    return t;
}

Node* parse() {
    if (posi < (int)S.size() && S[posi] == '[') {
        posi++; // '['
        Node* left = parse();
        if (posi >= (int)S.size() || S[posi] != '-') exit(0);
        posi++; // '-'
        string winner = parseName();
        if (posi >= (int)S.size() || S[posi] != '-') exit(0);
        posi++; // '-'
        Node* right = parse();
        if (posi >= (int)S.size() || S[posi] != ']') exit(0);
        posi++; // ']'
        Node* nd = new Node();
        nd->leaf = false;
        nd->name = winner;
        nd->l = left;
        nd->r = right;
        return nd;
    } else {
        string nm = parseName();
        Node* nd = new Node();
        nd->leaf = true;
        nd->name = nm;
        return nd;
    }
}

using State = map<string,int>;

struct Res {
    // champion name -> list of possible states
    map<string, vector<State>> mp;
};

static string encodeState(const State& st) {
    string key;
    for (auto &p : st) {
        key += p.first;
        key += '#';
        key += to_string(p.second);
        key += ';';
    }
    return key;
}

Res solve(Node* nd) {
    if (nd->leaf) {
        Res res;
        State st;
        st[nd->name] = 0;
        res.mp[nd->name].push_back(st);
        return res;
    }

    Res L = solve(nd->l);
    Res R = solve(nd->r);
    Res out;

    for (auto &pl : L.mp) {
        const string &cl = pl.first;
        for (auto &sl : pl.second) {
            for (auto &pr : R.mp) {
                const string &cr = pr.first;
                for (auto &sr : pr.second) {
                    if (nd->name != cl && nd->name != cr) continue;

                    State merged = sl;
                    bool ok = true;
                    for (auto &x : sr) {
                        if (merged.count(x.first)) {
                            // same contestant cannot appear in both sides in a valid knockout chart
                            ok = false;
                            break;
                        }
                        merged[x.first] = x.second;
                    }
                    if (!ok) continue;

                    merged[nd->name]++;

                    out.mp[nd->name].push_back(std::move(merged));
                }
            }
        }
    }

    // deduplicate states for each champion
    for (auto &p : out.mp) {
        vector<State> uniq;
        unordered_set<string> seen;
        for (auto &st : p.second) {
            string key = encodeState(st);
            if (!seen.count(key)) {
                seen.insert(key);
                uniq.push_back(st);
            }
        }
        p.second.swap(uniq);
    }

    return out;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> S)) return 0;

    map<string,int> reported;
