        // Let's assume the first participant in a match is the winner.
        // Then the string "[a,b]" means a beats b.
        // For nested: "[[a,b],c]" means first a beats b, then that winner (a) beats c.
        // So the winner of a match is the first element.
        // So for left and right, the winner is left (since left is first).
        // But wait: the format is [left,right] where left and right can be names or submatches.
        // The winner of the match is the first element (left).
        // So we need to propagate wins accordingly.
        // left and right each return the winner of their subtree.
        // The match winner is left.
        // So left gets an extra win for this match.
        // But careful: left already might have wins from its subtree.
        // So we add 1 win to the left winner.
        int winner = left;
        cont[winner].wins++;
        // The right participant also played and lost, so no win added.
        // But the right participant's wins from its subtree remain.
        return winner;
    } else {
        // It's a leaf: a contestant name
        int start = pos;
        while (chart[pos] && chart[pos] != ',' && chart[pos] != ']' && chart[pos] != '[') {
