typedef struct {
    int *ids;
    int cnt;
    int cap;
} Vec;

static void vec_init(Vec *v) {
    v->ids = NULL;
    v->cnt = 0;
    v->cap = 0;
}

static void vec_push(Vec *v, int x) {
    if (v->cnt == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->ids = (int *)realloc(v->ids, sizeof(int) * v->cap);
    }
    v->ids[v->cnt++] = x;
}

static void vec_free(Vec *v) {
    free(v->ids);
}

typedef struct {
    int winner;   /* contestant id who wins this subtree */
    Vec losers;   /* contestants directly/indirectly eliminated by this winner on the path */
} NodeRes;

static char *S;
static int pos;
static int max_id = 0;

/*
Assumed chart grammar:
  expr := number | '(' expr expr number ')'
where number is a positive integer contestant id,
and in "(A B W)" contestants/subtrees A and B play, and W is the winner id,
which must be the winner of either A or B.

For each internal match, the declared winner gets +1 win.
Leaves are contestants.

We verify whether the chart is structurally valid and then compare computed wins
with the reported ones.
*/

static void skip_spaces(void) {
    while (S[pos] && isspace((unsigned char)S[pos])) pos++;
}

static int parse_number(void) {
    skip_spaces();
    if (!isdigit((unsigned char)S[pos])) return -1;
    int x = 0;
    while (isdigit((unsigned char)S[pos])) {
        x = x * 10 + (S[pos] - '0');
        pos++;
    }
    if (x > max_id) max_id = x;
    return x;
}

static int *wins;
static int parse_ok = 1;

static NodeRes parse_expr(void) {
    NodeRes res;
    vec_init(&res.losers);
    res.winner = -1;

    skip_spaces();
    if (!parse_ok) return res;

    if (isdigit((unsigned char)S[pos])) {
        int id = parse_number();
        if (id < 0) {
            parse_ok = 0;
            return res;
        }
        res.winner = id;
        return res;
    }

    if (S[pos] == '(') {
        pos++;
        NodeRes L = parse_expr();
        NodeRes R = parse_expr();
        int w = parse_number();
        skip_spaces();
        if (S[pos] != ')') {
            parse_ok = 0;
            vec_free(&L.losers);
            vec_free(&R.losers);
            return res;
        }
        pos++;

        if (!parse_ok) {
            vec_free(&L.losers);
            vec_free(&R.losers);
            return res;
        }

        if (w != L.winner && w != R.winner) {
            parse_ok = 0;
            vec_free(&L.losers);
            vec_free(&R.losers);
            return res;
        }

        res.winner = w;
        wins[w]++;

        if (w == L.winner) {
            vec_push(&res.losers, R.winner);
        } else {
            vec_push(&res.losers, L.winner);
        }

        vec_free(&L.losers);
        vec_free(&R.losers);
        return res;
    }

    parse_ok = 0;
    return res;
}

