/*
 * JAG knockout tournament consistency check
 *
 * We are given:
 * - a tournament chart string S
 * - reported number of wins for each contestant
 *
 * The chart is a binary tree written recursively:
 *   [left-subtree][right-subtree][winner]
 * where a leaf is a contestant label.
 *
 * Contestant labels are uppercase letters 'A'..'Z'.
 * For every internal node, the winner must be one of the contestants
 * appearing in that node's subtree.
 *
 * We must determine whether there exists an assignment of actual match
 * winners consistent with the chart and such that each contestant's total
 * number of wins equals the reported value.
 *
 * Approach:
 * Parse the expression as a postorder tournament tree.
 * For each subtree, compute DP:
 *   dp[winner][mask of win-count vector] ... but direct vector DP is too large.
 *
 * Instead, note contestants are only 'A'..'Z', and the intended classic solution
 * is to compute for each subtree and each possible winner the set of possible
 * win-count additions encoded as a map from count-vectors to feasibility.
 *
 * To keep it practical in Java, we use HashSet<State> where State is int[] packed
 * into a string-like object. Since the original constraints for this problem are
 * small, this is sufficient.
 *
 * Parsing:
 * Read all input tokens. First token is S. Remaining integers are reported wins.
 * Their count determines number of contestants N, assumed to be A..(A+N-1).
 *
 * If the actual judge format differs slightly, this still handles the common form:
 *   S
 *   w0 w1 ... w(N-1)
 *
 * Output:
 *   "Yes" if consistent, otherwise "No"
 */
public class Main {
    static class Node {
        boolean leaf;
        int player;      // for leaf
        int winnerLabel; // label written at this internal node
        Node left, right;
        BitSet members;  // contestants appearing in subtree
    }

    static String S;
    static int pos;
    static int N;
    static int[] target;

    static class State {
        byte[] cnt; // counts for all N contestants

        State(int n) {
            cnt = new byte[n];
        }

        State(byte[] a) {
            cnt = a;
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof State)) return false;
            return Arrays.equals(cnt, ((State) o).cnt);
        }

        @Override
        public int hashCode() {
            return Arrays.hashCode(cnt);
        }
    }

    static class DPRes {
        @SuppressWarnings("unchecked")
        HashSet<State>[] byWinner = new HashSet[26];
        BitSet members = new BitSet(26);

        DPRes() {
            for (int i = 0; i < 26; i++) byWinner[i] = new HashSet<>();
        }
    }

    // Parse postorder expression:
    // if current char is uppercase letter and enough structure is not implied,
    // this problem's classic encoding is:
    // - leaves are uppercase letters
    // - internal node is formed by two subexpressions followed by uppercase winner
    //
    // Such grammar is ambiguous without subtree sizes, so we parse using stack:
    static Node buildFromPostorder(String s) {
        ArrayDeque<Node> st = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!Character.isUpperCase(c)) continue;
            int x = c - 'A';

            // Try to interpret as internal node when possible:
            // if there are at least 2 nodes on stack and x belongs to union of their members,
            // it can be an internal node. In this tournament notation, every internal marker
            // is also an uppercase contestant label, so this is the intended reduction.
            if (st.size() >= 2) {
                Node b = st.removeLast();
                Node a = st.removeLast();

                BitSet union = (BitSet) a.members.clone();
                union.or(b.members);

                if (union.get(x)) {
                    Node p = new Node();
                    p.leaf = false;
                    p.left = a;
                    p.right = b;
                    p.winnerLabel = x;
                    p.members = union;
                    st.addLast(p);
                    continue;
                } else {
                    // cannot be internal, restore and treat as leaf
                    st.addLast(a);
                    st.addLast(b);
                }
            }

            Node leaf = new Node();
            leaf.leaf = true;
            leaf.player = x;
            leaf.members = new BitSet(26);
            leaf.members.set(x);
            st.addLast(leaf);
        }
        if (st.size() != 1) return null;
        return st.peekLast();
    }

    static DPRes solve(Node node) {
        DPRes res = new DPRes();
        res.members.or(node.members);

        if (node.leaf) {
            State st = new State(N);
            if (node.player < N) {
                res.byWinner[node.player].add(st);
            }
            return res;
        }

        DPRes L = solve(node.left);
        DPRes R = solve(node.right);

        int w = node.winnerLabel;
        if (!node.left.members.get(w) && !node.right.members.get(w)) {
            return res;
        }

        // Winner must come from one side; that side's subtree winner must be w.
        // The other side winner can be any contestant from that side, and loses final.
        // Winner w gains +1 win at this internal node.
        if (node.left.members.get(w)) {
            HashSet<State> leftSet = L.byWinner[w];
            for (State ls : leftSet) {
                for (int rw = R.members.nextSetBit(0); rw >= 0; rw = R.members.nextSetBit(rw + 1)) {
                    for (State rs : R.byWinner[rw]) {
                        byte[] nc = new byte[N];
                        for (int i = 0; i < N; i++) nc[i] = (byte) (ls.cnt[i] + rs.cnt[i]);
                        if (w < N) nc[w]++;
                        if (fitsTarget(nc)) res.byWinner[w].add(new State(nc));
                    }
                }
            }
        }
        if (node.right.members.get(w)) {
            HashSet<State> rightSet = R.byWinner[w];
            for (State rs : rightSet) {
                for (int lw = L.members.nextSetBit(0); lw >= 0; lw = L.members.nextSetBit(lw + 1)) {
                    for (State ls : L.byWinner[lw]) {
                        byte[] nc = new byte[N];
                        for (int i = 0; i < N; i++) nc[i] = (byte) (ls.cnt[i] + rs.cnt[i]);
                        if (w < N) nc[w]++;
                        if (fitsTarget(nc)) res.byWinner[w].add(new State(nc));
                    }
                }
            }
        }

        return res;
    }

    static boolean fitsTarget(byte[] cnt) {
        for (int i = 0; i < N; i++) {
            if (cnt[i] > target[i]) return false;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        ArrayList<String> tokens = new ArrayList<>();
        String t;
        while ((t = fs.next()) != null) tokens.add(t);
        if (tokens.isEmpty()) return;

        S = tokens.get(0);

        ArrayList<Integer> vals = new ArrayList<>();
        for (int i = 1; i < tokens.size(); i++) {
            try {
                vals.add(Integer.parseInt(tokens.get(i)));
            } catch (NumberFormatException e) {
                // ignore non-integer extra tokens
            }
        }

        N = vals.size();
        target = new int[N];
        for (int i = 0; i < N; i++) target[i] = vals.get(i);

        Node root = buildFromPostorder(S);
        if (root == null) {
            System.out.println("No");
            return;
        }

        // Basic sanity: all contestants in chart should be among reported contestants.
        for (int x = root.members.nextSetBit(0); x >= 0; x = root.members.nextSetBit(x + 1)) {
            if (x >= N) {
                System.out.println("No");
                return;
            }
        }

        DPRes ans = solve(root);
        boolean ok = false;
        for (int w = root.members.nextSetBit(0); w >= 0 && !ok; w = root.members.nextSetBit(w + 1)) {
            for (State st : ans.byWinner[w]) {
                boolean same = true;
                for (int i = 0; i < N; i++) {
                    if (st.cnt[i] != target[i]) {
                        same = false;
                        break;
                    }
                }
                if (same) {
                    ok = true;
                    break;
                }
            }
        }

        System.out.println(ok ? "Yes" : "No");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
